// Seeded speckle texture for planting: a base colour with dots of the given colours.
function speckles(base, dots, density, size, seed) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 256;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, 256, 256);
  let state = seed;
  const random = () => (state = (state * 1664525 + 1013904223) % 4294967296) / 4294967296;
  for (let i = 0; i < density; i++) {
    ctx.fillStyle = dots[Math.floor(random() * dots.length)];
    const x = random() * 256, y = random() * 256, r = size * (.55 + random() * .9);
    for (const [dx, dy] of [[0, 0], [256, 0], [0, 256], [-256, 0], [0, -256]]) {
      ctx.beginPath();
      ctx.arc(x + dx, y + dy, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  const texture = new T.CanvasTexture(canvas);
  texture.wrapS = texture.wrapT = T.RepeatWrapping;
  texture.colorSpace = T.SRGBColorSpace;
  return texture;
}

// A planting bed that follows the ground: vertical sides, a clipped-hedge rim and a
// planted top, all `height` metres above the terrain surface.
function raisedBed(ring, surface, height, rim, materials) {
  const winding = Math.sign(signedArea(ring)) || 1;
  const inner = offsetRing(ring, winding, -rim);
  const rimPositions = [], topPositions = [], topUvs = [];
  const at = ([x, z], lift) => [x, surface(x, z) + lift, z];
  ring.forEach((point, i) => {
    const next = ring[(i + 1) % ring.length];
    const [a, b] = [at(point, -.2), at(next, -.2)];
    const [c, d] = [at(next, height - .08), at(point, height - .08)];
    const [e, f] = [at(inner[(i + 1) % ring.length], height), at(inner[i], height)];
    rimPositions.push(a, b, c, a, c, d, d, c, e, d, e, f);
  });
  for (const face of T.ShapeUtils.triangulateShape(inner.map(([x, z]) => new T.Vector2(x, z)), [])) {
    for (const i of face) {
      topPositions.push(at(inner[i], height + .02));
      topUvs.push([inner[i][0] / 3, inner[i][1] / 3]);
    }
  }
  const geometry = new T.BufferGeometry();
  geometry.setAttribute('position', new T.Float32BufferAttribute([...rimPositions, ...topPositions].flat(), 3));
  geometry.setAttribute('uv', new T.Float32BufferAttribute([...rimPositions.map(() => [0, 0]), ...topUvs].flat(), 2));
  geometry.addGroup(0, rimPositions.length, 0);
  geometry.addGroup(rimPositions.length, topPositions.length, 1);
  geometry.computeVertexNormals();
  const mesh = new T.Mesh(geometry, materials);
  mesh.castShadow = mesh.receiveShadow = true;
  return mesh;
}

function nearSegment(px, pz, ring, distance) {
  return ring.some(([ax, az], i) => {
    const [bx, bz] = ring[(i + 1) % ring.length];
    const dx = bx - ax, dz = bz - az;
    const t = Math.max(0, Math.min(1, ((px - ax) * dx + (pz - az) * dz) / (dx * dx + dz * dz || 1)));
    return Math.hypot(ax + t * dx - px, az + t * dz - pz) < distance;
  });
}

export function addRoseGarden(scene, surface, outline) {
  const group = new T.Group();
  const pickables = [];
  const points = [...layout.beds, ...layout.leaves, ...layout.gravel, layout.hedge].flat();
  const x0 = Math.min(...points.map(p => p[0])) - 2, x1 = Math.max(...points.map(p => p[0])) + 2;
  const z0 = Math.min(...points.map(p => p[1])) - 2, z1 = Math.max(...points.map(p => p[1])) + 2;

  // Gravel paths and the soil under the beds, on a sharper ground overlay than the
  // campus-wide ground texture.
  const canvas = document.createElement('canvas');
  const scale = Math.min(28, 2048 / Math.max(x1 - x0, z1 - z0));
  canvas.width = Math.ceil((x1 - x0) * scale);
  canvas.height = Math.ceil((z1 - z0) * scale);
  const ctx = canvas.getContext('2d');
  ctx.scale(scale, scale);
  ctx.translate(-x0, -z0);
  const trace = rings => {
    ctx.beginPath();
    for (const ring of rings) {
      ring.forEach(([x, z], i) => ctx[i ? 'lineTo' : 'moveTo'](x, z));
      ctx.closePath();
    }
  };
  trace(layout.gravel);
  ctx.fillStyle = '#e8e2d4';
  ctx.fill('evenodd');
  ctx.strokeStyle = '#c9c1ae';
  ctx.lineWidth = .14;
  ctx.stroke();
  trace([...layout.beds, ...layout.leaves]);
  ctx.fillStyle = '#4f4934';
  ctx.fill();
  ctx.strokeStyle = '#4f4934';
  ctx.lineWidth = .3;
  ctx.stroke();
  const texture = new T.CanvasTexture(canvas);
  texture.colorSpace = T.SRGBColorSpace;
  texture.anisotropy = 8;
  const columns = Math.ceil((x1 - x0) / 1.5), rows = Math.ceil((z1 - z0) / 1.5);
  const positions = [], uvs = [], indices = [];
  for (let j = 0; j <= rows; j++) {
    for (let i = 0; i <= columns; i++) {
      const x = x0 + (x1 - x0) * i / columns, z = z0 + (z1 - z0) * j / rows;
      positions.push(x, surface(x, z) + .05, z);
      uvs.push(i / columns, 1 - j / rows);
      if (i < columns && j < rows) {
        const a = j * (columns + 1) + i, b = a + 1, c = a + columns + 1, d = c + 1;
        indices.push(a, c, b, b, c, d);
      }
    }
  }
  const overlayGeometry = new T.BufferGeometry();
  overlayGeometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
  overlayGeometry.setAttribute('uv', new T.Float32BufferAttribute(uvs, 2));
  overlayGeometry.setIndex(indices);
  overlayGeometry.computeVertexNormals();
  const overlay = new T.Mesh(overlayGeometry, new T.MeshLambertMaterial({
    map: texture, transparent: true, alphaTest: .4, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -2,
  }));
  overlay.receiveShadow = true;
  group.add(overlay);

  // Rose beds: rose-pink, red and white flowers over dark foliage inside a clipped rim.
  const roses = new T.MeshLambertMaterial({side: T.DoubleSide, map: speckles('#56633a',
    ['#c63e5b', '#e2738b', '#f2b8c3', '#a3253a', '#f7ecee', '#d9566f', '#6f4a36'], 1700, 4.2, 7)});
  const rim = paint('#3e5c2b', T.DoubleSide);
  for (const ring of layout.beds) group.add(raisedBed(ring, surface, .6, .32, [rim, roses]));
  // Leaf beds of silver-green planting.
  const leaves = new T.MeshLambertMaterial({side: T.DoubleSide, map: speckles('#86a08c',
    ['#b4c8bb', '#6c8a72', '#d3ddd5', '#9fb3c4', '#7f9a83', '#c8d6c9'], 1500, 3.6, 11)});
  for (const ring of layout.leaves) group.add(raisedBed(ring, surface, .4, .2, [paint('#5f7a70', T.DoubleSide), leaves]));

  // Perimeter hedge, open where the gravel path leaves the garden.
  const batch = createBoxBatch();
  const hedge = paint('#35522a');
  let top = -Infinity;
  layout.hedge.slice(1).forEach(([bx, bz], i) => {
    const [ax, az] = layout.hedge[i];
    const length = Math.hypot(bx - ax, bz - az), steps = Math.ceil(length);
    const yaw = -Math.atan2(bz - az, bx - ax);
    for (let s = 0; s < steps; s++) {
      const t = (s + .5) / steps, x = ax + (bx - ax) * t, z = az + (bz - az) * t;
      if (layout.gravel.some(ring => nearSegment(x, z, ring, 1.4))) continue;
      const ground = surface(x, z);
      batch.add(hedge, x, ground + .65, z, length / steps + .05, 1.7, .95, yaw);
      top = Math.max(top, ground + 1.5);
    }
  });
  batch.flush(group, roseGardenId);

  group.traverse(object => {
    if (object.isMesh) {
      object.userData.osm = roseGardenId;
      pickables.push(object);
    }
  });
  scene.add(group);
  // Keep the generated trees off the beds and the hedge line.
  const exclusions = [...layout.beds, ...layout.leaves].map(ring => offsetRing(ring, Math.sign(signedArea(ring)) || 1, 1.5));
  layout.hedge.slice(1).forEach(([bx, bz], i) => {
    const [ax, az] = layout.hedge[i], length = Math.hypot(bx - ax, bz - az);
    const nx = -(bz - az) / length * 1.8, nz = (bx - ax) / length * 1.8;
    exclusions.push([[ax + nx, az + nz], [bx + nx, bz + nz], [bx - nx, bz - nz], [ax - nx, az - nz]]);
  });
  if (outline) exclusions.push(outline);
  return {pickables, top, exclusions};
}
